// ── CONFIG ────────────────────────────────────────────────────────────────
// ID of the Google Drive folder containing the uploaded video files.
// Get it from the URL: drive.google.com/drive/folders/<FOLDER_ID>
const DRIVE_FOLDER_ID = '1tf_Kf_wi6wu6mD6vI8CWlIHUhZXsg1TU';

return [{ json: { folderId: DRIVE_FOLDER_ID } }];

// Google Drive node outputs 1 item per file.
// Dedup by lowercase title — if same game appears multiple times,
// keep the first item (Drive node sorts by modifiedTime desc by default).

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const f = item.json;
  if (!f.name) continue;
  // Remove extension
  const title = f.name.replace(/\.[^/.]+$/, '').trim();
  if (!title) continue;
  const key = title.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  const drive_link = f.webViewLink || `https://drive.google.com/file/d/${f.id}/view`;
  out.push({ title, drive_link, file_name: f.name });
}

if (out.length === 0) {
  return [{ json: { sql: 'SELECT 1;', totalFiles: 0 } }];
}

// Pass the array to Postgres via json_to_recordset for server-side matching.
// shared_with = how many OTHER games (different bundle_id, with an evaluation row) carry the same
// title. 0 for one game or one game's iOS + Android pair: those are linked automatically.
// > 0: the file may belong to another game, so it is only suggested, for the evaluator to confirm.
const jsonLit = JSON.stringify(out);
const sql =
  `WITH f AS (\n` +
  `  SELECT * FROM json_to_recordset($jf$${jsonLit}$jf$::json)\n` +
  `    AS f(title text, drive_link text, file_name text)\n` +
  `), shared AS (\n` +
  `  SELECT lower(f.title) AS k, count(DISTINCT lower(g.bundle_id)) AS n\n` +
  `  FROM f\n` +
  `  JOIN game_info g ON lower(g.title) = lower(f.title)\n` +
  `  WHERE EXISTS (SELECT 1 FROM game_evaluations e WHERE e.game_id = g.game_id)\n` +
  `  GROUP BY 1\n` +
  `)\n` +
  `SELECT ge.id, ge.game_id, ge.category_group, f.drive_link, f.file_name,\n` +
  `  GREATEST(COALESCE(s.n, 1) - 1, 0) AS shared_with\n` +
  `FROM f\n` +
  `JOIN game_info gi ON lower(gi.title) = lower(f.title)\n` +
  `JOIN game_evaluations ge ON ge.game_id = gi.game_id\n` +
  `LEFT JOIN shared s ON s.k = lower(f.title)\n` +
  `WHERE COALESCE(ge.drive_link, '') = ''\n` +
  `  AND ge.initial_evaluator IS NOT NULL`;

return [{ json: { sql, totalFiles: out.length } }];

// One statement, two data-modifying CTEs:
//  upd: games whose title belongs to one game (shared_with = 0) get drive_link, as before.
//  sug: games whose title is shared by different games (shared_with > 0) get a row in
//       drive_link_suggestions instead; the missing-demo prompt shows it for the evaluator to confirm.
// Both only touch rows that still have no link, so an existing link is never overwritten.
// The sug CTE is left out when there is nothing to suggest, so migration 048 is only needed once
// a shared title actually shows up.

const rows = $input.all().map(i => i.json).filter(r => r.id && r.drive_link);

if (rows.length === 0) {
  return [{ json: { sql: 'SELECT 1;', count: 0, suggested: 0 } }];
}

const q = s => `'${String(s == null ? '' : s).replace(/'/g, "''")}'`;
const auto = rows.filter(r => !(Number(r.shared_with) > 0));
const shared = rows.filter(r => Number(r.shared_with) > 0);

const ctes = [];
if (auto.length) {
  const values = auto.map(r => `(${parseInt(r.id)}, ${q(r.drive_link)})`).join(',\n    ');
  ctes.push(
    `upd AS (\n` +
    `  UPDATE game_evaluations ge\n` +
    `  SET drive_link = v.drive_link, drive_date = NOW(), updated_at = NOW()\n` +
    `  FROM (VALUES\n    ${values}\n  ) AS v(id, drive_link)\n` +
    `  WHERE ge.id = v.id AND COALESCE(ge.drive_link, '') = ''\n` +
    `  RETURNING ge.id\n)`
  );
}
if (shared.length) {
  const values = shared
    .map(r => `(${parseInt(r.id)}, ${q(r.drive_link)}, ${q(r.file_name)}, ${parseInt(r.shared_with)})`)
    .join(',\n    ');
  ctes.push(
    `sug AS (\n` +
    `  INSERT INTO drive_link_suggestions (game_evaluation_id, link, file_name, shared_with)\n` +
    `  SELECT v.id, v.link, v.file_name, v.shared_with\n` +
    `  FROM (VALUES\n    ${values}\n  ) AS v(id, link, file_name, shared_with)\n` +
    `  JOIN game_evaluations ge ON ge.id = v.id\n` +
    `  WHERE COALESCE(ge.drive_link, '') = ''\n` +
    `  ON CONFLICT (game_evaluation_id) DO UPDATE\n` +
    `    SET link = EXCLUDED.link, file_name = EXCLUDED.file_name,\n` +
    `        shared_with = EXCLUDED.shared_with, suggested_at = NOW()\n` +
    `    WHERE drive_link_suggestions.link IS DISTINCT FROM EXCLUDED.link\n` +
    `  RETURNING game_evaluation_id\n)`
  );
}

const sql =
  `WITH ${ctes.join(',\n')}\n` +
  `SELECT ${auto.length ? '(SELECT count(*) FROM upd)' : '0'} AS auto_synced,\n` +
  `       ${shared.length ? '(SELECT count(*) FROM sug)' : '0'} AS suggested`;

return [{ json: { sql, count: auto.length, suggested: shared.length } }];

// auto_synced / suggested come from the statement itself: rows actually changed, not rows proposed.
const done = (() => { try { return $('Update drive_link2').first().json } catch { return {} } })();
const num = v => Number(v) || 0;
const totalFiles = (() => { try { return $('Parse File Names2').first().json.totalFiles || 0 } catch { return 0 } })();
return [{ json: {
  name: 'drive-video-link-sync',
  status: 'success',
  note: JSON.stringify({ total_files: totalFiles, matched_updated: num(done.auto_synced), suggested: num(done.suggested) }),
} }];

// Files whose whole name (minus one extension and one " (n)" suffix) is a 6-char code go to the code branch.
// Same rule as codeFromFileName in lib/short-code.ts (alphabet, 6 chars, >= 2 digits, >= 2 letters). Keep the alphabet identical (a test checks it).
const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const CODE_RE = new RegExp('^[' + CODE_ALPHABET + ']{6}$');
// A code mixes letters and digits (at least 2 of each), so a real title like "Racket" is never a code.
const MIN_DIGITS = 2;
const MIN_LETTERS = 2;
const isCode = s => {
  if (!CODE_RE.test(s)) return false;
  const digits = (s.match(/[2-9]/g) || []).length;
  return digits >= MIN_DIGITS && 6 - digits >= MIN_LETTERS;
};
const codeFromFileName = name => {
  const base = String(name)
    .replace(/\.[^.]*$/, '')
    .replace(/\s*\(\d+\)$/, '')
    .trim()
    .toUpperCase();
  return isCode(base) ? base : null;
};

const files = $input.all().map(i => i.json);
const codeFiles = [];
for (const f of files) {
  const code = f && f.name ? codeFromFileName(f.name) : null;
  if (!code) continue;
  codeFiles.push({
    code,
    id: f.id,
    name: f.name,
    drive_link: f.webViewLink || `https://drive.google.com/file/d/${f.id}/view`,
  });
}

if (codeFiles.length === 0) {
  return [{ json: { sql: 'SELECT 1 AS no_codes', codeFiles, files } }];
}

// The joins compare the plain columns game_info.demo_code / record_code with the code, so the partial
// unique indexes of migration 052 are used (game_info is 5.7 GB: never wrap the row in to_jsonb()).
// Migration 052 MUST be applied before this workflow is activated: without it the column does not exist,
// this query fails and every file falls back to title matching.
// One query for every code: which game owns it as a demo code, is it a record code instead, and
// can the link be written (some evaluation row of that game still has an empty drive_link).
// link_is_this_file: the game's link already points at this very file, so only the rename is missing.
const lit = JSON.stringify(codeFiles.map(c => ({ code: c.code, file_id: c.id, drive_link: c.drive_link })));
const sql =
  `SELECT c.code, c.file_id, c.drive_link,\n` +
  `  d.game_id AS demo_game_id, d.title AS demo_title,\n` +
  `  (r.game_id IS NOT NULL) AS in_record,\n` +
  `  EXISTS (SELECT 1 FROM game_evaluations e WHERE e.game_id = d.game_id AND COALESCE(e.drive_link, '') = '') AS can_write,\n` +
  `  EXISTS (SELECT 1 FROM game_evaluations e WHERE e.game_id = d.game_id AND e.drive_link LIKE '%' || c.file_id || '%') AS link_is_this_file\n` +
  `FROM json_to_recordset($jf$${lit}$jf$::json)\n` +
  `  AS c(code text, file_id text, drive_link text)\n` +
  `LEFT JOIN game_info d ON d.demo_code = c.code\n` +
  `LEFT JOIN game_info r ON r.record_code = c.code`;

return [{ json: { sql, codeFiles, files } }];

// Decide, per code file, what happens. Order of preference:
//   known demo code + a link can be written -> write the link, then rename the file to the game title
//   known demo code, link already this file -> only the rename is retried
//   known demo code, game already has a link -> link_exists (file untouched, flow_log + Chat)
//   code only in record_code                -> silent skip: the record workflow owns that file (shared
//                                              folder); nothing written, no notice, not on the title path
//   code in demo_code AND in record_code    -> ambiguous_code (file untouched, flow_log + Chat): the file
//                                              could be either video, so nothing is written
//   code in neither table                   -> NOT an error: the file stays on the title path
//                                              (a real title like "Racket" is 6 letters long)
const split = $('Split Code Files').first().json;
// An errored lookup (Lookup Codes continues on error and passes an item with `error`) or an empty
// result means no code is known: every file then stays on the title path and nothing is written.
const rows = $input.all().map(i => i.json).filter(r => r && !r.error && r.code);
const byCode = new Map(rows.map(r => [String(r.code), r]));
const q = s => `'${String(s == null ? '' : s).replace(/'/g, "''")}'`;

const claimed = new Set();
const seenCode = new Set();
const writes = [];
const renames = [];
const notices = [];

for (const c of split.codeFiles) {
  const r = byCode.get(c.code);
  const gameId = r && r.demo_game_id != null ? String(r.demo_game_id) : null;
  const inRecord = !!(r && r.in_record);
  if (gameId == null && !inRecord) continue; // unknown code: title path
  claimed.add(c.id);
  const base = { code: c.code, file: c.name, file_id: c.id, drive_link: c.drive_link };
  if (gameId == null) continue; // record code only: claimed above, left untouched for the record workflow
  const entry = { ...base, game_id: gameId, title: r.demo_title, file_name: c.name };
  if (inRecord) {
    notices.push({ ...entry, status: 'ambiguous_code', reason: 'the code is both a demo code and a record code' });
    continue;
  }
  if (seenCode.has(c.code)) {
    notices.push({ ...entry, status: 'link_exists', reason: 'another file with this code was handled in the same run' });
    continue;
  }
  seenCode.add(c.code);
  if (r.can_write) writes.push(entry);
  else if (r.link_is_this_file) renames.push(entry);
  else notices.push({ ...entry, status: 'link_exists', reason: 'the game already has a demo link' });
}

// One statement; only rows with an EMPTY drive_link are touched, for EVERY evaluation row of the game.
let writeSql = 'SELECT 1 AS none';
if (writes.length) {
  const values = writes.map(w => `(${q(w.game_id)}, ${q(w.drive_link)})`).join(',\n    ');
  writeSql =
    `WITH v(game_id, drive_link) AS (VALUES\n    ${values}\n), upd AS (\n` +
    `  UPDATE game_evaluations ge\n` +
    `  SET drive_link = v.drive_link, drive_date = NOW(), updated_at = NOW()\n` +
    `  FROM v\n` +
    `  WHERE ge.game_id::text = v.game_id AND COALESCE(ge.drive_link, '') = ''\n` +
    `  RETURNING ge.game_id\n` +
    `)\n` +
    `SELECT COALESCE((SELECT json_agg(DISTINCT game_id::text) FROM upd), '[]'::json) AS updated`;
}

const titleFiles = split.files.filter(f => !(f && claimed.has(f.id)));
return [{ json: { writeSql, writes, renames, notices, titleFiles } }];

// Hand the files that stay on the title path to the existing, unchanged "Parse File Names2".
// Parse File Names2 skips an item without a name, so an empty placeholder keeps its "no files" log row.
const files = $input.first().json.titleFiles || [];
return files.length ? files.map(json => ({ json })) : [{ json: {} }];

// Which files to rename: games the statement really updated, plus retries whose link already is this file.
const cls = $('Classify Codes').first().json;
const updated = new Set(((($input.first() || {}).json || {}).updated || []).map(String));
const key = e => `${e.game_id}|${e.file_id}`;
const written = new Set((cls.writes || []).map(key));
const todo = [
  ...(cls.writes || []).filter(e => updated.has(String(e.game_id))),
  ...(cls.renames || []).filter(e => !written.has(key(e))),
];
if (todo.length === 0) return [];

// Characters Drive and most tools dislike become a space; runs of spaces collapse.
const clean = s => String(s == null ? '' : s).replace(/[\/\\:*?"<>|]/g, ' ').replace(/\s+/g, ' ').trim();
const renames = todo.map(e => {
  const baseName = clean(e.title) || String(e.game_id);
  const m = String(e.file_name || '').match(/\.[^./]*$/);
  const ext = m ? m[0] : '';
  return { file_id: e.file_id, game_id: String(e.game_id), code: e.code, oldName: e.file_name, baseName, ext, newName: baseName + ext };
});

// One Drive query for every planned name, to see which are already taken in the folder.
const folderId = $('Config2').first().json.folderId;
const esc = s => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const names = renames.map(r => `name = '${esc(r.newName)}'`).join(' or ');
const nameQuery = `'${esc(folderId)}' in parents and trashed = false and (${names})`;
return [{ json: { renames, nameQuery } }];

// A name already in the folder, or planned twice in this run, gets _<game_id> appended.
const plan = $('Plan Renames').first().json.renames;
const taken = new Set($input.all().map(i => i.json && i.json.name).filter(Boolean));
const used = new Set();
const out = [];
for (const r of plan) {
  let newName = r.newName;
  if (taken.has(newName) || used.has(newName)) newName = `${r.baseName}_${r.game_id}${r.ext}`;
  used.add(newName);
  out.push({ json: { fileId: r.file_id, newName, game_id: r.game_id, code: r.code, oldName: r.oldName } });
}
return out;

// The Drive node runs with "continue on error", so a failed rename arrives as an item with `error`.
const items = $input.all().map(i => i.json);
const failed = items.filter(j => j && j.error).length;
const renamed = items.length - failed;
return [{ json: {
  name: 'drive-video-link-sync',
  status: failed ? 'rename_failed' : 'code_linked',
  note: JSON.stringify({ renamed, failed, files: items.filter(j => j && j.name).map(j => j.name) }),
} }];

// One flow_log row + one Chat message per code file that was left as it is. A file is reported once per
// status: List Drive Files2 lists the last 7 days of the folder on every run, and a held file would otherwise
// be reported again each time. (Workflow static data is kept for production runs only.)
const notices = $('Classify Codes').first().json.notices || [];
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const sent = new Set(store && Array.isArray(store.demoNoticeKeys) ? store.demoNoticeKeys : []);

const out = [];
for (const n of notices) {
  const key = `${n.status}|${n.file_id}`;
  if (sent.has(key)) continue;
  sent.add(key);
  const label = n.title ? `${n.title} (${n.game_id})` : n.game_id || '';
  let text;
  if (n.status === 'ambiguous_code') {
    text = `drive-video-link-sync: ${n.file} carries code ${n.code}, which is both a demo code and a record code (demo code of ${label}). File left as it is; the code must be fixed in the database before this file is processed.`;
  } else {
    text = `drive-video-link-sync: ${n.file} carries code ${n.code} for ${label}, which already has a demo link. File left as it is; clear the old link to process it again.`;
  }
  out.push({ json: {
    name: 'drive-video-link-sync',
    status: n.status,
    note: JSON.stringify({ file: n.file, code: n.code, game_id: n.game_id || null, reason: n.reason || null }),
    text,
  } });
}
if (store) store.demoNoticeKeys = [...sent].slice(-1000);
return out;
